//! The StykAnimate design system for the native app.
//!
//! One source of truth for how the interface looks, in plain Rust so the shell, the panels and the tests read the same
//! values:
//!
//! - [`tokens`]: the colours, scales and shadows of `src/styles/tokens.css`, both themes, generated by
//!   `cargo xtask design generate` (never edited by hand; `cargo xtask design check` fails when stale). Each
//!   constant's doc comment names its CSS custom property so a porter can find the stylesheet's use of it.
//! - [`icons`]: the interface's Lucide icons, as SVG, looked up by the names the JavaScript uses.
//! - [`fonts`]: Inter and Inter Tight, bundled.
//! - With the `widgets` feature, [`widgets`]: the iced side (conversions, font handles, the icon widget), and
//!   [`typography`]: the type roles as iced fonts, sizes and line heights (`docs/native/typography.md`).
//!
//! It depends on iced only behind `widgets`, and never on the engine or the core.

pub mod fonts;
pub mod icons;
mod icon_table;
pub mod tokens;
#[cfg(all(feature = "widgets", windows, test))]
mod direct_write;
#[cfg(feature = "widgets")]
pub mod glyphs;
#[cfg(feature = "widgets")]
pub mod grayscale;
#[cfg(feature = "widgets")]
pub mod typography;
#[cfg(feature = "widgets")]
pub mod warm_up;
#[cfg(feature = "widgets")]
pub mod widgets;

pub use tokens::Palette;

/// A colour as CSS computes it: red, green and blue bytes and alpha as a fraction, not premultiplied.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Rgba {
    /// Red, 0 to 255.
    pub r: u8,
    /// Green, 0 to 255.
    pub g: u8,
    /// Blue, 0 to 255.
    pub b: u8,
    /// Opacity, 0 to 1.
    pub a: f32,
}

impl Rgba {
    /// A colour from its channels.
    pub const fn new(r: u8, g: u8, b: u8, a: f32) -> Rgba {
        Rgba { r, g, b, a }
    }

    /// `#rrggbb`, or `#rrggbbaa` when not opaque (the alpha rounded to a byte, as CSS serializes it).
    pub fn to_hex(self) -> String {
        if self.a >= 1.0 {
            format!("#{:02x}{:02x}{:02x}", self.r, self.g, self.b)
        } else {
            format!("#{:02x}{:02x}{:02x}{:02x}", self.r, self.g, self.b, (self.a * 255.0).round() as u8)
        }
    }
}

/// One entry of a CSS `box-shadow` list.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct BoxShadow {
    /// Drawn inside the box.
    pub inset: bool,
    /// Horizontal offset in logical pixels.
    pub x: f32,
    /// Vertical offset in logical pixels.
    pub y: f32,
    /// Blur radius in logical pixels.
    pub blur: f32,
    /// Spread radius in logical pixels.
    pub spread: f32,
    /// The shadow's colour.
    pub color: Rgba,
}

/// A composite type role (`--type-*`): what CSS sets with the `font` shorthand.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct TypeRole {
    /// Font weight, 100 to 900.
    pub weight: f32,
    /// Size in logical pixels.
    pub size: f32,
    /// Line height in logical pixels.
    pub line_height: f32,
    /// The family stack, as CSS writes it.
    pub family: &'static str,
}

/// The two themes.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Theme {
    /// The brand default.
    #[default]
    Light,
    /// First-class dark.
    Dark,
}

impl Theme {
    /// The semantic roles of this theme.
    pub const fn palette(self) -> &'static Palette {
        match self {
            Theme::Light => &tokens::LIGHT,
            Theme::Dark => &tokens::DARK,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn hex_round_trips_the_opaque_and_translucent_forms() {
        assert_eq!(tokens::primitives::MIST_175.to_hex(), "#eceff4");
        assert_eq!(Rgba::new(0, 0, 0, 0.5).to_hex(), "#00000080");
    }

    #[test]
    fn the_top_bar_height_follows_the_ui_scale_as_the_css_computes_it() {
        // `--topbar-h: max(52px, calc(44px / var(--ui-scale)))`
        assert_eq!(tokens::scale::topbar_h(1.0), 52.0);
        assert_eq!(tokens::scale::topbar_h(2.0), 52.0);
        assert_eq!(tokens::scale::topbar_h(0.5), 88.0);
    }

    #[test]
    fn the_themes_have_their_own_surfaces() {
        assert_eq!(Theme::Light.palette().surface_field.to_hex(), "#eceff4");
        assert_ne!(Theme::Light.palette().surface, Theme::Dark.palette().surface);
        assert_eq!(Theme::default(), Theme::Light);
    }
}
